CREATE OR REPLACE FUNCTION public.async_create_match(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare cached jsonb; mid uuid; mem uuid; code text; out jsonb;
begin
 if auth.uid() is null then raise exception 'authentication required'; end if;
 cached:=public.async_cached(p_request_id,'create'); if cached is not null then return cached; end if;
 loop code:=upper(substr(encode(gen_random_bytes(6),'hex'),1,6)); exit when not exists(select 1 from public.async_matches where room_code=code); end loop;
 insert into public.async_matches(room_code,created_by) values(code,auth.uid()) returning id into mid;
 insert into public.async_members(match_id,user_id,team,slot_number,turn_position) values(mid,auth.uid(),'A',1,1) returning id into mem;
 out:=jsonb_build_object('match_id',mid,'member_id',mem,'room_code',code,'team','A');
 perform public.async_store(p_request_id,'create',out); return out;
end$function$

CREATE OR REPLACE FUNCTION public.async_finish_turn(p_match_id uuid, p_expected_version bigint, p_expected_hash text, p_snapshot jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare cached jsonb; m public.async_matches%rowtype; me uuid; active_unit text; next_member uuid; h text; nextv bigint; out jsonb;
begin
 cached:=public.async_cached(p_request_id,'finish_turn'); if cached is not null then return cached; end if;
 select id into me from public.async_members where match_id=p_match_id and user_id=auth.uid();
 select * into m from public.async_matches where id=p_match_id for update;
 if me is null or m.active_member_id<>me then raise exception 'not your turn'; end if;
 if m.state_version<>p_expected_version or m.snapshot_hash is distinct from p_expected_hash then raise exception 'stale state/hash'; end if;
 if m.turn_started_at is null then raise exception 'turn was not started'; end if;
 if clock_timestamp()>m.turn_deadline then raise exception 'turn deadline expired'; end if;
 if not public.async_snapshot_valid(p_snapshot) or coalesce((p_snapshot->>'turnSequence')::bigint,-1)<>m.turn_sequence+1 then raise exception 'invalid next snapshot'; end if;
 active_unit:=public.async_snapshot_active_unit(p_snapshot);
 select id into next_member from public.async_members where match_id=m.id and ('online-'||team||'-'||slot_number)=active_unit;
 if next_member is null then raise exception 'snapshot authority does not match roster'; end if;
 h:=public.async_hash(p_snapshot);nextv:=m.state_version+1;
 update public.async_matches set status=case when coalesce((p_snapshot#>>'{battle,ended}')::boolean,false) then 'finished' else 'waiting' end,snapshot=p_snapshot,snapshot_hash=h,timeout_snapshot=null,timeout_snapshot_hash=null,state_version=nextv,turn_sequence=m.turn_sequence+1,active_member_id=next_member,turn_started_at=null,turn_deadline=null,waiting_deadline=clock_timestamp()+interval '12 hours',updated_at=clock_timestamp() where id=m.id;
 out:=jsonb_build_object('ok',true,'state_version',nextv,'snapshot_hash',h,'active_member_id',next_member);
 insert into public.async_audit(match_id,user_id,operation,state_version) values(m.id,auth.uid(),'finish_turn',nextv);
 perform public.async_store(p_request_id,'finish_turn',out); return out;
end$function$

CREATE OR REPLACE FUNCTION public.async_initialize_match(p_match_id uuid, p_snapshot jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare cached jsonb; m public.async_matches%rowtype; active_unit text; active_member uuid; h text; out jsonb;
begin
 cached:=public.async_cached(p_request_id,'initialize'); if cached is not null then return cached; end if;
 select * into m from public.async_matches where id=p_match_id for update;
 if m.id is null or not public.async_is_member(m.id) then raise exception 'not a member'; end if;
 if m.status<>'forming' then raise exception 'already initialized'; end if;
 if (select count(*) from public.async_members where match_id=m.id)<>2 or exists(select 1 from public.async_members where match_id=m.id and (not ready or champion_id is null)) then raise exception 'both players must be ready'; end if;
 if not public.async_snapshot_valid(p_snapshot) or coalesce((p_snapshot->>'turnSequence')::bigint,-1)<>0 then raise exception 'invalid initial snapshot'; end if;
 active_unit:=p_snapshot#>>'{battle,order,0}';
 select id into active_member from public.async_members where match_id=m.id and ('online-'||team||'-'||slot_number)=active_unit;
 if active_member is null then raise exception 'snapshot active unit does not match roster'; end if;
 h:=public.async_hash(p_snapshot);
 update public.async_matches set status='waiting',snapshot=p_snapshot,snapshot_hash=h,state_version=1,turn_sequence=0,active_member_id=active_member,turn_started_at=null,turn_deadline=null,waiting_deadline=clock_timestamp()+interval '12 hours',updated_at=clock_timestamp() where id=m.id;
 out:=jsonb_build_object('ok',true,'match_id',m.id,'state_version',1,'snapshot_hash',h,'active_member_id',active_member);
 insert into public.async_audit(match_id,user_id,operation,state_version) values(m.id,auth.uid(),'initialize',1);
 perform public.async_store(p_request_id,'initialize',out); return out;
end$function$

CREATE OR REPLACE FUNCTION public.async_join_match(p_room_code text, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare cached jsonb; m public.async_matches%rowtype; mem uuid; out jsonb;
begin
 if auth.uid() is null then raise exception 'authentication required'; end if;
 cached:=public.async_cached(p_request_id,'join'); if cached is not null then return cached; end if;
 select * into m from public.async_matches where room_code=upper(trim(p_room_code)) for update;
 if m.id is null then raise exception 'room not found'; end if;
 if m.status<>'forming' then raise exception 'room already started'; end if;
 select id into mem from public.async_members where match_id=m.id and user_id=auth.uid();
 if mem is null then
   if (select count(*) from public.async_members where match_id=m.id)>=2 then raise exception 'room full'; end if;
   insert into public.async_members(match_id,user_id,team,slot_number,turn_position) values(m.id,auth.uid(),'B',1,2) returning id into mem;
 end if;
 out:=jsonb_build_object('match_id',m.id,'member_id',mem,'room_code',m.room_code,'team',(select team from public.async_members where id=mem));
 perform public.async_store(p_request_id,'join',out); return out;
end$function$

CREATE OR REPLACE FUNCTION public.async_prepare_member(p_match_id uuid, p_champion_id text, p_loadout jsonb, p_deploy_x integer, p_deploy_y integer, p_ready boolean, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare cached jsonb; mem public.async_members%rowtype; out jsonb;
begin
 cached:=public.async_cached(p_request_id,'prepare'); if cached is not null then return cached; end if;
 if jsonb_typeof(p_loadout)<>'array' or jsonb_array_length(p_loadout)>4 or (p_ready and jsonb_array_length(p_loadout)<>4) then raise exception 'loadout must contain exactly 4 skills when ready'; end if;
 if p_deploy_x not between 0 and 11 or p_deploy_y not between 0 and 11 then raise exception 'invalid deployment'; end if;
 select * into mem from public.async_members where match_id=p_match_id and user_id=auth.uid() for update;
 if mem.id is null then raise exception 'not a member'; end if;
 if (select status from public.async_matches where id=p_match_id)<>'forming' then raise exception 'match already initialized'; end if;
 update public.async_members set champion_id=p_champion_id,loadout=p_loadout,deploy_x=p_deploy_x,deploy_y=p_deploy_y,ready=p_ready where id=mem.id;
 out:=jsonb_build_object('ok',true,'member_id',mem.id); perform public.async_store(p_request_id,'prepare',out); return out;
end$function$

CREATE OR REPLACE FUNCTION public.async_promote_timeouts(p_match_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare m public.async_matches%rowtype; active_unit text; next_member uuid; nextv bigint;
begin
 select * into m from public.async_matches where id=p_match_id for update;
 if m.id is null or not public.async_is_member(m.id) then raise exception 'not a member'; end if;
 if m.status='waiting' and m.turn_started_at is null and clock_timestamp()>m.waiting_deadline then update public.async_matches set status='expired',updated_at=clock_timestamp() where id=m.id; return jsonb_build_object('status','expired'); end if;
 if m.turn_started_at is null or clock_timestamp()<=m.turn_deadline then return jsonb_build_object('status',m.status); end if;
 if not public.async_snapshot_valid(m.timeout_snapshot) then raise exception 'timeout snapshot missing or invalid'; end if;
 active_unit:=public.async_snapshot_active_unit(m.timeout_snapshot);
 select id into next_member from public.async_members where match_id=m.id and ('online-'||team||'-'||slot_number)=active_unit;
 if next_member is null then raise exception 'timeout authority does not match roster'; end if;
 nextv:=m.state_version+1;
 update public.async_matches set status=case when coalesce((timeout_snapshot#>>'{battle,ended}')::boolean,false) then 'finished' else 'waiting' end,snapshot=timeout_snapshot,snapshot_hash=timeout_snapshot_hash,state_version=nextv,turn_sequence=m.turn_sequence+1,active_member_id=next_member,timeout_snapshot=null,timeout_snapshot_hash=null,turn_started_at=null,turn_deadline=null,waiting_deadline=clock_timestamp()+interval '12 hours',updated_at=clock_timestamp() where id=m.id;
 insert into public.async_audit(match_id,user_id,operation,state_version) values(m.id,auth.uid(),'timeout',nextv);
 return jsonb_build_object('status','promoted','state_version',nextv,'active_member_id',next_member);
end$function$

CREATE OR REPLACE FUNCTION public.async_start_turn(p_match_id uuid, p_expected_version bigint, p_timeout_snapshot jsonb, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare cached jsonb; m public.async_matches%rowtype; me uuid; th text; out jsonb;
begin
 cached:=public.async_cached(p_request_id,'start_turn'); if cached is not null then return cached; end if;
 select id into me from public.async_members where match_id=p_match_id and user_id=auth.uid();
 select * into m from public.async_matches where id=p_match_id for update;
 if me is null or m.active_member_id<>me then raise exception 'not your turn'; end if;
 if m.status not in ('waiting','active') then raise exception 'match not playable'; end if;
 if m.state_version<>p_expected_version then raise exception 'stale state version'; end if;
 if m.turn_started_at is not null then
   out:=jsonb_build_object('ok',true,'match',to_jsonb(m)); perform public.async_store(p_request_id,'start_turn',out); return out;
 end if;
 if clock_timestamp()>m.waiting_deadline then update public.async_matches set status='expired',updated_at=clock_timestamp() where id=m.id; raise exception 'waiting deadline expired'; end if;
 if not public.async_snapshot_valid(p_timeout_snapshot) or coalesce((p_timeout_snapshot->>'turnSequence')::bigint,-1)<>m.turn_sequence+1 then raise exception 'invalid timeout snapshot'; end if;
 th:=public.async_hash(p_timeout_snapshot);
 update public.async_matches set status='active',turn_started_at=clock_timestamp(),turn_deadline=clock_timestamp()+interval '30 seconds',timeout_snapshot=p_timeout_snapshot,timeout_snapshot_hash=th,updated_at=clock_timestamp() where id=m.id returning * into m;
 out:=jsonb_build_object('ok',true,'match',to_jsonb(m)); insert into public.async_audit(match_id,user_id,operation,state_version) values(m.id,auth.uid(),'start_turn',m.state_version);
 perform public.async_store(p_request_id,'start_turn',out); return out;
end$function$

